#include <gtk/gtk.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
static double cpu(void) { struct timespec t; if (clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&t)) return -1; return t.tv_sec+t.tv_nsec/1e9; }
int main(void) {
    const char *paths[] = {"/usr/share/icons"};
    const char *names[] = {"document-open", "document-save", "edit-copy", "window-close"};
    gint64 t=g_get_monotonic_time(); double c=cpu();
    GtkIconTheme *theme=gtk_icon_theme_new();
    gtk_icon_theme_set_search_path(theme,paths,1);
    gtk_icon_theme_set_custom_theme(theme,"Adwaita");
    printf("construct_us=%" G_GINT64_FORMAT " cpu_s=%.6f\n",g_get_monotonic_time()-t,cpu()-c);
    t=g_get_monotonic_time();c=cpu();
    GList *icons=gtk_icon_theme_list_icons(theme,NULL);
    printf("list_us=%" G_GINT64_FORMAT " cpu_s=%.6f\n",g_get_monotonic_time()-t,cpu()-c);
    if (!icons) return 2;
    icons=g_list_sort(icons,(GCompareFunc)g_strcmp0);
    GChecksum *sum=g_checksum_new(G_CHECKSUM_SHA256);
    for (GList *p=icons;p;p=p->next) {g_checksum_update(sum,p->data,strlen(p->data));g_checksum_update(sum,(const guchar*)"\n",1);}
    printf("icons_count=%u icons_sha256=%s\n",g_list_length(icons),g_checksum_get_string(sum));
    g_checksum_free(sum);g_list_free_full(icons,g_free);
    for (unsigned i=0;i<G_N_ELEMENTS(names);i++) {
        t=g_get_monotonic_time();c=cpu();
        GtkIconInfo *info=gtk_icon_theme_lookup_icon(theme,names[i],24,0);
        if (!info || !gtk_icon_info_get_filename(info)) return 3;
        printf("lookup=%s us=%" G_GINT64_FORMAT " cpu_s=%.6f file=%s\n",names[i],g_get_monotonic_time()-t,cpu()-c,gtk_icon_info_get_filename(info));
        g_object_unref(info);
    }
    FILE *maps=fopen("/proc/self/maps","r"); if (!maps) return 4;
    char line[8192];unsigned mapped=0;
    while(fgets(line,sizeof(line),maps)) if(strstr(line,"icon-theme.cache")){printf("cache_map=%s",line);mapped++;}
    fclose(maps);printf("mapped_cache_regions=%u\n",mapped);
    g_object_unref(theme);return 0;
}
